    "use strict";
    function Bullet() {
        this.x = 0;
        this.y = 0;
        this.z = 0;
        this.dx = 0;
        this.dy = 0;
        this.dz = 0;
        this.ttl = 0;
        this.active = false;
        this.player = null;
        this.damage = 20;
        if (typeof BulletActor != "undefined") this.actor = new BulletActor(this);
    }
    Bullet.prototype.remove = function() {
        munitionsManager.bulletPool.recycle(this);
        if (this.actor) this.actor.remove();
    };
    Bullet.prototype.update = function(delta) {
        if (munitionsManager.projectileCollidesWithSomething(this)) {
            return;
        }
        if (this.ttl <= 0) {
            this.remove();
            return;
        }
        this.x += this.dx * delta;
        this.y += this.dy * delta;
        this.z += this.dz * delta;
        this.ttl -= delta;
        if (this.actor) this.actor.update();
    };
    Bullet.prototype.fire = function(player, pos, dir, dmg, ttl, speed) {
        this.player = player;
        this.x = pos.x;
        this.y = pos.y;
        this.z = pos.z;
        this.dx = dir.x * speed;
        this.dy = dir.y * speed;
        this.dz = dir.z * speed;
        this.ttl = ttl;
        this.damage = dmg;
        this.active = true;
        if (this.actor) this.actor.fire();
    };
    Bullet.prototype.collidesWithMap = function(res) {
        if (this.actor) {
            var loc = munitionsManager.getMapIntersectionPoint(this, res);
            if (loc) {
                bulletHoleManager.addHole(0, loc.x, loc.y, loc.z);
            }
        }
        this.remove();
    };
    Bullet.prototype.collidesWithPlayer = function(player) {
        if (!this.actor) {
            tv1.x = this.dx;
            tv1.y = this.dy;
            tv1.z = this.dz;
            tv2.x = player.x - this.x;
            tv2.y = player.y + .32 - this.y;
            tv2.z = player.z - this.z;
            var dist = BABYLON.Vector3.Cross(tv1, tv2);
            var damage = this.damage / (1 + dist.length() * 20);
            hitPlayer(player, this.player, damage, tv1.x, tv1.z);
        }
        this.remove();
    };
    var Slot = {
        Primary: 0,
        Secondary: 1
    };
    var ItemType = {
        Hat: 1,
        Stamp: 2,
        Primary: 3,
        Secondary: 4
    };
    var CharClass = {
        Soldier: 0,
        Scrambler: 1,
        Ranger: 2,
        Eggsploder: 3
    };
    CharClass.length = Object.keys(CharClass).length;
    catalog = new Catalog();
    function Catalog() {
        if (Items === undefined || Items === null) {
            throw "Items is undefined or null, cannot create Catalog";
        }
        this.isSetup = false;
        this.filterItems = function(itemList, filterFunc) {
            var filteredItems = [];
            for (var i = 0; i < itemList.length; i++) {
                if (filterFunc(itemList[i])) {
                    filteredItems.push(itemList[i]);
                }
            }
            return filteredItems;
        };
        this.findItemInListById = function(itemId, itemList) {
            for (var i = 0; i < itemList.length; i++) {
                if (itemList[i] && itemList[i].id === itemId) {
                    return itemList[i];
                }
            }
            return null;
        };
        this.findItemById = function(itemId) {
            return this.findItemInListById(itemId, Items);
        };
        this.findItemBy8BitItemId = function(itemType, classIdx, itemId8Bit) {
            if (this.isSetup === false) {
                this.setupCatalog();
            }
            var realItemId = itemId8Bit;
            switch (itemType) {
              case ItemType.Hat:
                if (itemId8Bit === 0) {
                    return null;
                }
                realItemId += 999;
                return this.findItemInListById(realItemId, this.hats);

              case ItemType.Stamp:
                if (itemId8Bit === 0) {
                    return null;
                }
                realItemId += 1999;
                return this.findItemInListById(realItemId, this.stamps);

              case ItemType.Primary:
                realItemId += 3e3;
                switch (classIdx) {
                  case CharClass.Soldier:
                    realItemId += 100;
                    break;

                  case CharClass.Scrambler:
                    realItemId += 600;
                    break;

                  case CharClass.Ranger:
                    realItemId += 400;
                    break;

                  case CharClass.Eggsploder:
                    realItemId += 800;
                    break;
                }
                try {
                    if (classIdx === undefined || classIdx === null || classIdx < 0 || classIdx > CharClass.length) {
                        console.log("classIdx is invalid: " + classIdx);
                        console.log("itemType: " + itemType);
                        console.log("itemId8Bit: " + itemId8Bit);
                    }
                } catch (err) {
                    console.log("I heard you like errors so I put an error in your error: " + err.message);
                }
                return this.findItemInListById(realItemId, this.forClass[classIdx].forWeaponSlot[Slot.Primary]);

              case ItemType.Secondary:
                realItemId += 3e3;
                return this.findItemInListById(realItemId, this.forClass[classIdx].forWeaponSlot[Slot.Secondary]);
            }
        };
        this.get8BitItemId = function(item, classIdx) {
            if (item === null) {
                return 0;
            }
            if (this.isSetup === false) {
                this.setupCatalog();
            }
            var itemId8Bit = item.id;
            switch (item.item_type_id) {
              case ItemType.Hat:
                itemId8Bit -= 999;
                break;

              case ItemType.Stamp:
                itemId8Bit -= 1999;
                break;

              case ItemType.Primary:
                itemId8Bit = itemId8Bit - 3e3;
                switch (classIdx) {
                  case CharClass.Soldier:
                    itemId8Bit -= 100;
                    break;

                  case CharClass.Scrambler:
                    itemId8Bit -= 600;
                    break;

                  case CharClass.Ranger:
                    itemId8Bit -= 400;
                    break;

                  case CharClass.Eggsploder:
                    itemId8Bit -= 800;
                    break;
                }
                break;

              case ItemType.Secondary:
                itemId8Bit -= 3e3;
                break;
            }
            return itemId8Bit;
        };
        this.addWeaponFunctions = function(weaponItem) {
            weaponItem.instantiateNew = function(avatar) {
                var instance = new this.item_data.class(avatar, this.item_data.meshName);
                if (avatar.actor) {
                    avatar.actor.setWeaponSkeleton(instance.actor.skeleton);
                }
                return instance;
            };
        };
        this.getTaggedItems = function(tag) {
            var filterTagFunc = function(item) {
                if (item.item_data.tags !== undefined && item.item_data.tags !== null && item.item_data.tags.length > 0) {
                    for (var i = 0; i < item.item_data.tags.length; i++) {
                        if (item.item_data.tags[i] === tag) {
                            return true;
                        }
                    }
                }
                return false;
            };
            return this.filterItems(Items, filterTagFunc);
        };
        this.setupCatalog = function() {
            this.hats = [];
            this.stamps = [];
            this.primaryWeapons = [];
            this.secondaryWeapons = [];
            this.forClass = [];
            for (var i = 0; i < Items.length; i++) {
                switch (Items[i].item_type_id) {
                  case ItemType.Hat:
                    this.hats.push(Items[i]);
                    break;

                  case ItemType.Stamp:
                    this.stamps.push(Items[i]);
                    break;

                  case ItemType.Primary:
                    this.primaryWeapons.push(Items[i]);
                    this.addWeaponFunctions(Items[i]);
                    break;

                  case ItemType.Secondary:
                    this.secondaryWeapons.push(Items[i]);
                    this.addWeaponFunctions(Items[i]);
                    break;
                }
            }
            for (var cIdx = 0; cIdx < CharClass.length; cIdx++) {
                var isFreeSharedFunc = function(item) {
                    return item.price === 0 && item.exclusive_for_class === null;
                };
                var isFreeClassExclusiveFunc = function(item) {
                    return item.price === 0 && item.exclusive_for_class === cIdx;
                };
                var isPaidSharedFunc = function(item) {
                    return item.price > 0 && item.exclusive_for_class === null;
                };
                var isPaidClassExclusiveFunc = function(item) {
                    return item.price > 0 && item.exclusive_for_class === cIdx;
                };
                var outer = this;
                var createClassWeaponListFunc = function(itemList) {
                    var itemList = outer.filterItems(itemList, isFreeSharedFunc).concat(outer.filterItems(itemList, isFreeClassExclusiveFunc)).concat(outer.filterItems(itemList, isPaidSharedFunc)).concat(outer.filterItems(itemList, isPaidClassExclusiveFunc));
                    return itemList;
                };
                var classItems = {
                    primaryWeapons: createClassWeaponListFunc(this.primaryWeapons),
                    secondaryWeapons: createClassWeaponListFunc(this.secondaryWeapons)
                };
                classItems.forWeaponSlot = [ classItems.primaryWeapons, classItems.secondaryWeapons ];
                this.forClass.push(classItems);
            }
            this.isSetup = true;
        };
        if (this.isSetup === false) {
            this.setupCatalog();
        }
    }
    function Collider() {
        this.playerCollisionMesh = BABYLON.MeshBuilder.CreateBox("pc", {
            size: .5,
            height: .6
        }, scene);
        this.playerCollisionMesh.position.y = .3;
        this.playerCollisionMesh.bakeCurrentTransformIntoVertices();
        this.playerCollisionMesh.setEnabled(false);
        this.wedgeCollisionMesh = BABYLON.MeshBuilder.CreateBox("", {
            size: 1.5
        }, scene);
        this.wedgeCollisionMesh.position.y = -.75;
        this.wedgeCollisionMesh.bakeCurrentTransformIntoVertices();
        this.wedgeCollisionMesh.rotation.x = -Math.PI / 4;
        this.wedgeCollisionMesh.bakeTransformIntoVertices(this.wedgeCollisionMesh.getWorldMatrix());
        this.wedgeCollisionMesh.setEnabled(false);
        this.iwedgeCollisionMesh = BABYLON.MeshBuilder.CreateBox("", {
            size: 1.5
        }, scene);
        this.iwedgeCollisionMesh.position.y = .75;
        this.iwedgeCollisionMesh.bakeCurrentTransformIntoVertices();
        this.iwedgeCollisionMesh.rotation.x = -Math.PI / 4;
        this.iwedgeCollisionMesh.bakeTransformIntoVertices(this.iwedgeCollisionMesh.getWorldMatrix());
        this.iwedgeCollisionMesh.setEnabled(false);
        this.projectileCollisionBox = BABYLON.MeshBuilder.CreateBox("", {
            size: .05
        });
        this.projectileCollisionBox.setEnabled(false);
    }
    Collider.prototype.playerCollidesWithMap = function(player) {
        return this.meshCollidesWithMap(this.playerCollisionMesh, player);
    };
    Collider.prototype.meshCollidesWithMap = function(mesh, pos) {
        var cellsChecked = {};
        var bbox = mesh.getBoundingInfo().boundingBox;
        for (var i = 0; i < bbox.vectors.length; i++) {
            var cx = Math.floor(pos.x + bbox.vectors[i].x);
            var cy = Math.floor(pos.y + bbox.vectors[i].y);
            var cz = Math.floor(pos.z + bbox.vectors[i].z);
            if (cx < 0 || cx >= map.width || cz < 0 || cz >= map.depth || cy < 0) return true;
            var checkId = cx + cy * 1e3 + cz * 1e4;
            if (cy < map.height) {
                if (!cellsChecked[checkId]) {
                    var res = this.meshCollidesWithCell(mesh, pos, cx, cy, cz);
                    if (res) return res;
                    cellsChecked[checkId] = true;
                }
            }
        }
        return false;
    };
    Collider.prototype.meshCollidesWithCell = function(mesh, pos, cx, cy, cz, ignoreSoft) {
        var cell = map.data[cx][cy][cz];
        if (cell.idx) {
            var mapMesh = mapMeshes[cell.idx];
            if (ignoreSoft && mapMesh.softness) {
                return false;
            }
            switch (mapMesh.colliderType) {
              case "full":
                return {
                    x: cx,
                    y: cy,
                    z: cz,
                    cell: cell
                };

              case "none":
                break;

              default:
                mesh.position.x = pos.x - cx - .5;
                mesh.position.y = pos.y - cy - .5;
                mesh.position.z = pos.z - cz - .5;
                mesh.setPivotPoint(new BABYLON.Vector3(-mesh.position.x, -mesh.position.y, -mesh.position.z));
                mesh.rotation.x = -cell.rx * Math.PI90;
                mesh.rotation.y = -cell.ry * Math.PI90;
                mesh.rotation.z = -cell.rz * Math.PI90;
                mesh.computeWorldMatrix();
                switch (mapMesh.colliderType) {
                  case "wedge":
                    if (this.wedgeCollisionMesh.intersectsMesh(mesh, true)) {
                        return {
                            x: cx,
                            y: cy,
                            z: cz,
                            cell: cell
                        };
                    }
                    break;

                  case "iwedge":
                    if (this.iwedgeCollisionMesh.intersectsMesh(mesh, true)) {
                        return {
                            x: cx,
                            y: cy,
                            z: cz,
                            cell: cell
                        };
                    }
                    break;

                  case "ladder":
                    if (mesh.name != "pc") break;

                  case "aabb":
                    if (mapMesh.colliderMesh.intersectsMesh(mesh, false, true)) {
                        return {
                            x: cx,
                            y: cy,
                            z: cz,
                            cell: cell
                        };
                    }
                    break;

                  case "obb":
                    if (mapMesh.colliderMesh.intersectsMesh(mesh, true, true)) {
                        return {
                            x: cx,
                            y: cy,
                            z: cz,
                            cell: cell
                        };
                    }
                    break;

                  default:
                    break;
                }
            }
        }
        return false;
    };
    Collider.prototype.projectileCollidesWithMap = function(pos, direction, ignoreSoft) {
        var dest = pos.subtract(direction);
        var cells = [ {
            x: pos.x,
            y: pos.y,
            z: pos.z
        } ];
        var cellsChecked = {};
        for (var i = 0; i < cells.length; i++) {
            var cx = Math.floor(cells[i].x);
            var cy = Math.floor(cells[i].y);
            var cz = Math.floor(cells[i].z);
            if (cx < 0 || cx >= map.width || cz < 0 || cz >= map.depth || cy < 0) return false;
            var checkId = cx + cy * 1e3 + cz * 1e4;
            if (cy < map.height) {
                if (!cellsChecked[checkId]) {
                    cellsChecked[checkId] = true;
                    var res = this.meshCollidesWithCell(this.projectileCollisionBox, pos, cx, cy, cz, ignoreSoft);
                    if (res && mapMeshes[res.cell.idx].softness != "verysoft") {
                        return res;
                    }
                }
            }
        }
        return false;
    };
