    "use strict";
    function Grenade() {
        this.x = 0;
        this.y = 0;
        this.z = 0;
        this.dx = 0;
        this.dy = 0;
        this.dz = 0;
        this.ttl = 0;
        this.active = false;
        this.player = null;
        if (typeof GrenadeActor != "undefined") this.actor = new GrenadeActor(this);
    }
    Grenade.prototype.update = function(delta) {
        if (this.ttl <= 0) {
            munitionsManager.grenadePool.recycle(this);
            if (this.actor) {
                addExplosion(this.x, this.y, this.z, this.damage);
                var pos = new BABYLON.Vector3(this.x, this.y, this.z);
                this.actor.explodeSound.setPosition(pos);
                this.actor.explodeSound.play();
                this.actor.remove();
            } else {
                checkExplosionCollisions(this);
            }
            return;
        }
        var pdx = this.dx;
        var pdy = this.dy;
        var pdz = this.dz;
        this.dy -= .003 * delta;
        var ndx = .5 * (this.dx + pdx) * delta;
        var ndy = .5 * (this.dy + pdy) * delta;
        var ndz = .5 * (this.dz + pdz) * delta;
        this.dx *= Math.pow(.99, delta);
        this.dz *= Math.pow(.99, delta);
        this.x += ndx;
        if (this.collidesWithMap()) {
            this.x -= ndx;
            this.dx *= -.5;
            this.dy *= .8;
            this.dz *= .8;
        }
        this.y += ndy;
        if (this.collidesWithMap()) {
            this.y -= ndy;
            this.dx *= .8;
            this.dy *= -.5;
            this.dz *= .8;
        }
        this.z += ndz;
        if (this.collidesWithMap()) {
            this.z -= ndz;
            this.dx *= .8;
            this.dy *= .8;
            this.dz *= -.5;
        }
        this.ttl -= delta;
        if (this.actor) {
            this.actor.update();
        }
    };
    Grenade.prototype.throw = function(player, pos, vec) {
        this.player = player;
        this.x = pos.x;
        this.y = pos.y;
        this.z = pos.z;
        this.dx = vec.x;
        this.dy = vec.y;
        this.dz = vec.z;
        this.ttl = 150;
        this.damage = 120;
        this.active = true;
        if (this.actor) this.actor.throw();
    };
    Grenade.prototype.collidesWithMap = function() {
        var res = collider.projectileCollidesWithMap(new BABYLON.Vector3(this.x, this.y - .07, this.z), new BABYLON.Vector3(this.dx, this.dy, this.dz));
        if (res) {
            if (this.actor) {
                this.actor.bounce();
            }
            return true;
        }
        return false;
    };
