    var mapMeshes;
    var duplicateWarningIssued = false;
    function loadMapMeshes(scene, onComplete) {
        mapMeshes = [ null ];
        var barrier = BABYLON.MeshBuilder.CreateBox("SPECIAL.barrier.full.verysoft", {
            size: 1
        }, scene);
        var mat = new BABYLON.StandardMaterial();
        mat.diffuseColor = BABYLON.Color3.Red();
        mat.emissiveColor = BABYLON.Color3.Red();
        mat.specularColor = BABYLON.Color3.Black();
        mat.wireframe = true;
        barrier.material = mat;
        barrier.setEnabled(false);
        mapMeshes.push(barrier);
        var shape = [];
        for (var i = 0; i <= 1; i += .125) {
            var a = -Math.PI / 2 + Math.PI * i;
            var x = Math.cos(a);
            var y = Math.sin(a + .05) * .5 + .5;
            x = Math.pow(x, 1.3) * .25;
            y = Math.pow(y, 1.3) * .6 - .48;
            shape.push(new BABYLON.Vector3(x, y, 0));
        }
        var egg = BABYLON.MeshBuilder.CreateLathe("SPECIAL.spawn-blue.none", {
            shape: shape,
            tessellation: 12
        }, scene);
        var mat = new BABYLON.StandardMaterial();
        mat.diffuseColor = new BABYLON.Color3(0, .5, 1);
        mat.specularColor = new BABYLON.Color3(.1, .2, .4);
        mat.specularPower = 8;
        egg.material = mat;
        egg.setEnabled(false);
        mapMeshes.push(egg);
        var egg = BABYLON.MeshBuilder.CreateLathe("SPECIAL.spawn-red.none", {
            shape: shape,
            tessellation: 12
        }, scene);
        var mat = new BABYLON.StandardMaterial();
        mat.diffuseColor = new BABYLON.Color3(1, .25, .25);
        mat.specularColor = new BABYLON.Color3(.4, .3, .3);
        mat.specularPower = 8;
        egg.material = mat;
        egg.setEnabled(false);
        mapMeshes.push(egg);
        loadMeshes(scene, [ "map" ], function(mesh) {
            if (mesh.parent) return;
            mapMeshes.push(mesh);
        }, function() {
            for (var i = 1; i < mapMeshes.length; i++) {
                var mesh = mapMeshes[i].getChildMeshes()[0];
                if (mesh) {
                    mapMeshes[i].colliderMesh = mesh;
                }
            }
            onComplete();
        });
    }
    function loadObjectMeshes(scene, onComplete) {
        loadMeshes(scene, [ "egg", "gun_eggk47", "gun_csg1", "gun_cluck9mm", "gun_dozenGauge", "gun_rpegg", "eggExplode", "munitions", "muzzleFlash", "items", "reticle" ], null, onComplete);
    }
