    function loadMaterials(scene) {
        var mat;
        mat = new BABYLON.StandardMaterial("bullet", scene);
        mat.emissiveColor = new BABYLON.Color3(1, 1, 1);
        if (shadowGen) {
            var definesList = [ "#define RECEIVESHADOWS" ];
            if (engineCaps.textureFloat) {
                definesList.push("#define SHADOWFULLFLOAT");
            }
        } else {
            var definesList = [];
        }
        definesList.push("#define DIRT");
        mat = new BABYLON.ShaderMaterial("map", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv" ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor" ],
            defines: definesList
        });
        if (shadowGen) {
            mat.setTexture("shadowSampler", shadowGen.getShadowMapForRendering());
            mat.setMatrix("shadowLightMat", shadowGen.getTransformMatrix());
            mat.setVector3("shadowParams", shadowGen.getDarkness(), shadowGen.getShadowMap().getSize().width, shadowGen.bias);
        }
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
        };
        mat = new BABYLON.ShaderMaterial("mapNoShadow", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv" ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor" ],
            defines: [ "#define DIRT" ]
        });
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            var scene = mesh.getScene();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
        };
        mat = new BABYLON.ShaderMaterial("standard", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv", BABYLON.VertexBuffer.MatricesIndicesKind, BABYLON.VertexBuffer.MatricesWeightsKind ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor", "colorMult" ],
            defines: [ "#define COLORMULT" ]
        });
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            var scene = mesh.getScene();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
            effect.setColor3("colorMult", mesh.colorMult || BABYLON.Color3.White());
            if (mesh.useBones && mesh.computeBonesUsingShaders && mesh.skeleton) {
                var matrices = mesh.skeleton.getTransformMatrices(mesh);
                if (matrices && effect) {
                    effect.setMatrices("mBones", matrices);
                }
            }
        };
        mat = new BABYLON.ShaderMaterial("standardInstanced", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv", "world0", "world1", "world2", "world3" ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor" ],
            defines: [ "#define INSTANCES" ]
        });
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            var scene = mesh.getScene();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
        };
        mat = new BABYLON.ShaderMaterial("eggShell", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv" ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor", "hp", "cameraPosition", "outlineColor", "colorMult", "stampOffset" ],
            defines: [ "#define EGGSHELL" ]
        });
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            var scene = mesh.getScene();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
            effect.setFloat("hp", mesh.player.hp / 100);
            effect.setColor3("colorMult", mesh.colorMult || BABYLON.Color3.White());
            effect.setFloat3("cameraPosition", scene.activeCamera.globalPosition.x, scene.activeCamera.globalPosition.y, scene.activeCamera.globalPosition.z);
            effect.setColor4("outlineColor", mesh.outlineColor, mesh.outlineColor.a);
            effect.setFloat2("stampOffset", mesh.stampU, mesh.stampV);
        };
        mat = new BABYLON.ShaderMaterial("emissive", scene, "standard", {
            attributes: [ "position", "normal", "color", "uv" ],
            uniforms: [ "world", "view", "viewProjection", "vFogInfos", "vFogColor", "emissiveColor" ],
            defines: [ "#define FLASH" ]
        });
        mat.onBind = function(mesh) {
            var effect = mesh.material.getEffect();
            var scene = mesh.getScene();
            effect.setFloat4("vFogInfos", scene.fogMode, scene.fogStart, scene.fogEnd, scene.fogDensity);
            effect.setColor3("vFogColor", scene.fogColor);
            effect.setColor3("emissiveColor", mesh.emissiveColor || BABYLON.Color3.Black());
        };
        mat = new BABYLON.StandardMaterial("wireframe", scene);
        mat.wireframe = true;
        mat = new BABYLON.StandardMaterial("normalBackface", scene);
        mat.diffuseColor = new BABYLON.Color3(.5, .5, .5);
        mat.ambientColor = new BABYLON.Color3(.5, .5, .5);
        mat.specularColor = new BABYLON.Color3(0, 0, 0);
        mat.backFaceCulling = false;
        mat.twoSidedLighting = true;
        mat = new BABYLON.StandardMaterial("muzzleFlash", scene);
        mat.emissiveColor = BABYLON.Color3.White();
        mat = new BABYLON.StandardMaterial("ui", scene);
        mat.disableLighting = true;
        mat.emissiveColor = BABYLON.Color3.White();
        mat.fogEnabled = false;
        mat = new BABYLON.StandardMaterial("eggWhite", scene);
        mat.disableLighting = true;
        mat.alpha = .8;
        mat.emissiveColor = BABYLON.Color3.White();
        mat = new BABYLON.StandardMaterial("eggYolk", scene);
        mat.disableLighting = true;
        mat.emissiveColor = BABYLON.Color3.White();
    }
    function loadMeshes(scene, meshNames, onMeshLoaded, onComplete) {
        var meshCount = meshNames.length;
        var that = this;
        var mat = scene.getMaterialByName("standard");
        var numEggs = 0;
        var numHands = 0;
        for (var idx = 0; idx < meshCount; idx++) {
            var rootUrl = "models/";
            var path = meshNames[idx] + ".babylon";
            if (typeof window === "undefined") {
                var data = fs.readFileSync(path, "utf8");
                data = data.replace(/\r?\n|\r/g, "");
                path = "data:" + data;
                rootUrl = "";
            }
            BABYLON.SceneLoader.ImportMesh("", rootUrl, path, scene, function(meshes, partcileSystems, skeletons) {
                try {
                    for (var m = 0; m < meshes.length; m++) {
                        var mesh = meshes[m];
                        if (mesh.name == "egg") numEggs++;
                        if (mesh.name == "hands") numHands++;
                        if (!duplicateWarningIssued && (numEggs > 1 || numHands > 1)) {
                            duplicateWarningIssued = true;
                            alert("Duplicate egg and/or hand models detected.\n\nOpen the weapon models in Blender and make sure egg/hands layers are turned off, then re-export.");
                        }
                        if (mesh.setMaterial) mesh.setMaterial(mat);
                        mesh.setEnabled(false);
                        mesh.isPickable = false;
                        if (onMeshLoaded) onMeshLoaded(mesh);
                    }
                    meshCount--;
                    if (meshCount == 0 && onComplete) {
                        onComplete.call(that);
                    }
                } catch (e) {
                    console.log(e);
                }
            });
        }
    }
    "use strict";
    function Rocket() {
        this.x = 0;
        this.y = 0;
        this.z = 0;
        this.dx = 0;
        this.dy = 0;
        this.dz = 0;
        this.ttl = 0;
        this.ttArmed = 0;
        this.active = false;
        this.player = null;
        this.damage = 120;
        if (typeof RocketActor != "undefined") this.actor = new RocketActor(this);
    }
    Rocket.prototype.remove = function() {
        munitionsManager.rocketPool.recycle(this);
        if (this.actor) this.actor.remove();
    };
    Rocket.prototype.update = function(delta) {
        if (munitionsManager.projectileCollidesWithSomething(this)) {
            return;
        }
        if (this.ttl <= 0) {
            this.explode();
            return;
        }
        this.x += this.dx * delta;
        this.y += this.dy * delta;
        this.z += this.dz * delta;
        this.ttl -= delta;
        this.ttArmed -= delta;
        if (this.actor) this.actor.update();
    };
    Rocket.prototype.fire = function(player, pos, dir, dmg, ttl, speed) {
        this.player = player;
        this.x = pos.x;
        this.y = pos.y;
        this.z = pos.z;
        this.dx = dir.x * speed;
        this.dy = dir.y * speed;
        this.dz = dir.z * speed;
        this.ttl = ttl;
        this.ttArmed = 0;
        this.damage = dmg;
        this.active = true;
        if (this.actor) this.actor.fire();
    };
    Rocket.prototype.explode = function() {
        if (this.actor) {
            addExplosion(this.x, this.y, this.z, this.damage);
            var pos = new BABYLON.Vector3(this.x, this.y, this.z);
            this.actor.explodeSound.setPosition(pos);
            this.actor.explodeSound.play();
        } else {
            checkExplosionCollisions(this);
        }
        this.remove();
    };
    Rocket.prototype.poof = function() {
        if (this.actor) {
            var pos = new BABYLON.Vector3(this.x, this.y, this.z);
            this.actor.poofSound.setPosition(pos);
            this.actor.poofSound.play();
            var animSpeed = .1;
            var size = .4;
            for (var i = 0; i < 10; i++) {
                var dx = Math.random() * .2 - .1;
                var dy = Math.random() * .2 - .1;
                var dz = Math.random() * .2 - .1;
                addExplosionSprite(explosionSmokeManager, animSpeed, pos.x, pos.y, pos.z, dx, dy, dz, size, false);
            }
        }
        this.remove();
    };
    Rocket.prototype.collidesWithMap = function(res) {
        this.x -= this.dx;
        this.y -= this.dy;
        this.z -= this.dz;
        if (this.ttArmed <= 0) {
            this.explode();
        } else {
            if (this.actor) {
                var loc = munitionsManager.getMapIntersectionPoint(this, res);
                if (loc) {
                    bulletHoleManager.addHole(0, loc.x, loc.y, loc.z);
                }
            }
            this.poof();
        }
    };
    Rocket.prototype.collidesWithPlayer = function(player) {
        if (this.ttArmed <= 0) {
            if (!this.actor) {
                hitPlayer(player, this.player, 255, tv1.x, tv1.z);
            }
            this.explode();
        } else {
            if (!this.actor) {
                hitPlayer(player, this.player, 10, tv1.x, tv1.z);
            }
            this.poof();
        }
    };
    function isBadWord(word) {
        word = " " + word + " ";
        var str = word.toLowerCase().replace(/[^a-zA-Z0-9|!\|@|$|;|¡]/g, "").replace(/6|g/g, "9").replace(/b/g, "6").replace(/\||l|i|1|;|¡/g, "!").replace(/e/g, "3").replace(/a|@/g, "4").replace(/o/g, "0").replace(/s|\$/g, "5").replace(/t/g, "7").replace(/z/g, "2").replace(/7h3|my|y0ur|7h3!r|h!5|h3r/g, "");
        var i1 = str.search(/( 94y | cum| 455 )/);
        str.replace(/ /g, "");
        var reg = /(4fr!c4n|kn336r0|5ch00!5h007|73rr0r!5t|卐|卍|qu33r|d!ck|w4nk|p!55|7357!c|735735|64!!5|nu75|nu72|j3w|k!k3|r374r|4u7!5|d0wn55|6006|8d|p0rn|5w4!!0w|347m3|347my|d!k|0r4!|5p0093|fuk|j!2|5u!c!d|m4573r6|5p0063|5p3rm|p3nu5|pu55y|6u7753x|fux|6u77h0!3|4n4!|4nu5|k!!!b!4ck5|murd3rb!4ck5|h!7!3r|w3764ck|49!n4|94y|455h0!3|5uck|j3w|5p!c|ch!nk|n!994|n!993|n!663|n!994|n!664|5h!7|6!7ch|fuck|cun7|kkk|wh0r3|f49|7w47|p3n!|r4p3w0m|r4p39!r|r4p!57|r4p3r|r4p!n|c0ck|7!75|900k|d!ckh34d)/;
        var i2 = str.search(reg);
        str.replace(/(.)(?=\1)/g, "");
        var i3 = str.search(reg);
        return i1 > -1 || i2 > -1 || i3 > -1;
    }
