    function loadBannerAd() {
        if (document.getElementById("overlay").style.display != "none") {
            return;
        }
        document.getElementById("placeholder_300x250").style.display = "none";
        document.getElementById("multisizeBannerAdPlaceholder").style.display = "none";
        if (inGame && betweenRounds) {
            displayBannerAd("bannerAdContainer", "houseAd_300x250");
            ga("send", "event", {
                eventCategory: "House banner ad",
                eventAction: "show",
                eventLabel: smallAds[smallAdIdx].label
            });
        } else {
            if (inGame) {
                var tag = "shellshock-io_multisize";
                displayBannerAd("gameAdContainer", tag);
                if (!aipMultisizeBannerDisplayed) {
                    aiptag.cmd.display.push(function() {
                        aipDisplayBannerForTag(tag);
                    });
                    aipMultisizeBannerDisplayed = true;
                } else {
                    aiptag.cmd.display.push(function() {
                        aipRefreshBannerForTag(tag);
                    });
                }
            } else {
                if (Math.random() * 100 <= smallAd_HouseAdPercentChance) {
                    displayBannerAd("bannerAdContainer", "houseAd_300x250");
                    return;
                }
                var tag = "shellshock-io_300x250";
                displayBannerAd("bannerAdContainer", tag);
                if (!aipBannerDisplayed) {
                    aiptag.cmd.display.push(function() {
                        aipDisplayBannerForTag(tag);
                    });
                    aipBannerDisplayed = true;
                } else {
                    aiptag.cmd.display.push(function() {
                        aipRefreshBannerForTag(tag);
                    });
                }
            }
        }
    }
