    "use strict";
    function BulletActor(bullet) {
        this.bullet = bullet;
        this.delayFrames = 0;
        this.mesh = scene.getMeshByName("bullet").createInstance("");
        this.mesh.setEnabled(false);
    }
    BulletActor.prototype.fire = function() {
        if (this.bullet.player.id == meId) {
            this.delayFrames = Math.ceil(ping / 17) + 5;
        } else {
            this.delayFrames = 5;
        }
        this.mesh.position.x = this.bullet.x;
        this.mesh.position.y = this.bullet.y;
        this.mesh.position.z = this.bullet.z;
        this.mesh.lookAt(new BABYLON.Vector3(this.bullet.x + this.bullet.dx, this.bullet.y + this.bullet.dy, this.bullet.z + this.bullet.dz));
        this.mesh.rotation.x += .015;
        this.mesh.rotation.y -= .015;
        this.mesh.scaling.z = .5;
    };
    BulletActor.prototype.update = function() {
        if (--this.delayFrames <= 0) {
            this.mesh.setEnabled(true);
        }
        this.mesh.position.x = this.bullet.x;
        this.mesh.position.y = this.bullet.y;
        this.mesh.position.z = this.bullet.z;
        if (this.bullet.player.id != meId) {
            this.mesh.scaling.z = Math.min(this.mesh.scaling.z + .03, 3);
        }
    };
    BulletActor.prototype.remove = function() {
        this.mesh.setEnabled(false);
    };
    "use strict";
    var Comm = {
        output: function(size) {
            this.buffer = new Uint8Array(size);
            this.idx = 0;
            this.packInt8 = function(val) {
                this.buffer[this.idx] = val & 255;
                this.idx++;
            };
            this.packInt16 = function(val) {
                this.buffer[this.idx] = val & 255;
                this.buffer[this.idx + 1] = val >> 8 & 255;
                this.idx += 2;
            };
            this.packInt32 = function(val) {
                this.buffer[this.idx] = val & 255;
                this.buffer[this.idx + 1] = val >> 8 & 255;
                this.buffer[this.idx + 2] = val >> 16 & 255;
                this.buffer[this.idx + 3] = val >> 24 & 255;
                this.idx += 4;
            };
            this.packRadU = function(val) {
                this.packInt16(val * 1e4);
            };
            this.packRad = function(val) {
                this.packInt16((val + Math.PI) * 1e4);
            };
            this.packFloat = function(val) {
                this.packInt16(val * 300);
            };
            this.packDouble = function(val) {
                this.packInt32(val * 1e6);
            };
            this.packString = function(str) {
                this.packInt8(str.length);
                for (var i = 0; i < str.length; i++) {
                    this.packInt16(str.charCodeAt(i));
                }
            };
        },
        input: function(buf) {
            this.buffer = new Uint8Array(buf);
            this.idx = 0;
            this.isMoreDataAvailable = function() {
                return Math.max(0, this.buffer.length - this.idx);
            };
            this.unPackInt8U = function() {
                var i = this.idx;
                this.idx++;
                return this.buffer[i];
            };
            this.unPackInt8 = function() {
                var v = this.unPackInt8U();
                return (v + 128) % 256 - 128;
            };
            this.unPackInt16U = function() {
                var i = this.idx;
                this.idx += 2;
                return this.buffer[i] + (this.buffer[i + 1] << 8);
            };
            this.unPackInt32U = function() {
                var i = this.idx;
                this.idx += 4;
                return this.buffer[i] + this.buffer[i + 1] * 256 + this.buffer[i + 2] * 65536 + this.buffer[i + 3] * 16777216;
            };
            this.unPackInt16 = function() {
                var v = this.unPackInt16U();
                return (v + 32768) % 65536 - 32768;
            };
            this.unPackInt32 = function() {
                var v = this.unPackInt32U();
                return (v + 2147483648) % 4294967296 - 2147483648;
            };
            this.unPackRadU = function() {
                return this.unPackInt16U() / 1e4;
            };
            this.unPackRad = function() {
                var v = this.unPackRadU();
                return v - Math.PI;
            };
            this.unPackFloat = function() {
                return this.unPackInt16() / 300;
            };
            this.unPackDouble = function() {
                return this.unPackInt32() / 1e6;
            };
            this.unPackString = function(maxLen) {
                maxLen = maxLen || 1e3;
                var len = Math.min(this.unPackInt8U(), maxLen);
                var str = new String();
                for (var i = 0; i < len; i++) {
                    var c = this.unPackInt16U();
                    if (c > 0) str += String.fromCharCode(c);
                }
                return str;
            };
        }
    };
