    function HitIndicator() {
        this.mesh = new BABYLON.Mesh("hitIndicator", gameScene);
        this.mesh.updatable = true;
        this.mesh.hasVertexAlpha = true;
        this.positions = [ 0, 0, 0, 0, .5, 0, .5, .5, 0, .5, 0, 0, .5, -.5, 0, 0, -.5, 0, -.5, -.5, 0, -.5, 0, 0, -.5, .5, 0 ];
        var indices = [ 0, 1, 8, 0, 2, 1, 0, 2, 1, 0, 3, 2, 0, 3, 2, 0, 4, 3, 0, 4, 3, 0, 5, 4, 0, 5, 4, 0, 6, 5, 0, 6, 5, 0, 7, 6, 0, 7, 6, 0, 8, 7, 0, 8, 7, 0, 1, 8 ];
        this.colors = new Array(48).fill(0);
        for (var i = 0; i < 48; i += 4) {
            this.colors[i] = 1;
            this.colors[i + 1] = .9;
            this.colors[i + 2] = 0;
            this.colors[i + 3] = -.5;
        }
        var vertexData = new BABYLON.VertexData();
        vertexData.positions = this.positions;
        vertexData.indices = indices;
        vertexData.colors = this.colors;
        vertexData.applyToMesh(this.mesh, true);
        this.mesh.layerMask = 536870912;
        this.mesh.material = gameScene.getMaterialByName("ui");
        this.resize();
    }
    HitIndicator.prototype.resize = function() {
        this.mesh.scaling.x = engine.getRenderWidth();
        this.mesh.scaling.y = engine.getRenderHeight();
    };
    HitIndicator.prototype.update = function(delta) {
        for (var i = 7; i < 48; i += 4) {
            this.colors[i] -= (this.colors[i] + .5) / 10 * delta;
        }
        var mult = Math.pow(.9, delta);
        if (me && me.playing) {
            camera.position.x *= mult;
            camera.position.z *= mult;
        }
        this.mesh.updateVerticesData(BABYLON.VertexBuffer.ColorKind, this.colors, true);
    };
    HitIndicator.prototype.hit = function(dx, dz) {
        var a = Math.radRange(-Math.atan2(dx, -dz) - me.yaw + .393);
        a = Math.floor(a / Math.PI2 * 8);
        var vec = new BABYLON.Vector2(-this.positions[a * 3 + 3], -this.positions[a * 3 + 4]).normalize();
        camera.position.x = vec.x * .03;
        camera.position.z = vec.y * .03;
        this.colors[a * 4 + 7] = 2;
    };
    function Reticle() {
        this.mesh = new BABYLON.AbstractMesh("reticle", gameScene);
        this.mesh.position.z = 1;
        this.lines = [];
        var reticleMesh = gameScene.getMeshByName("reticle");
        reticleMesh.setMaterial(gameScene.getMaterialByName("ui"));
        for (var i = 0; i < 4; i++) {
            var line = reticleMesh.createInstance("", this.mesh);
            line.parent = this.mesh;
            line.scaling = new BABYLON.Vector3(1, 1, 1);
            line.rotation.z = i * Math.PI / 2;
            this.lines.push(line);
        }
        this.mesh.setLayerMask(536870912);
        this.mesh.setEnabled(false);
        this.resize();
    }
    Reticle.prototype.show = function() {
        this.mesh.setEnabled(true);
    };
    Reticle.prototype.hide = function() {
        this.mesh.setEnabled(false);
    };
    Reticle.prototype.update = function(delta) {
        if (me.weapon) {
            for (var i = 0; i < 4; i++) {
                var a = i * Math.PI / 2;
                var spread = me.shotSpread + me.weapon.subClass.accuracy;
                this.lines[i].position.x = -Math.sin(a) * spread;
                this.lines[i].position.y = Math.cos(a) * spread;
            }
        }
    };
    Reticle.prototype.resize = function() {
        var scale = engine.getRenderHeight() / 640;
        this.mesh.scaling.x = scale;
        this.mesh.scaling.y = scale;
    };
