    Customizer.prototype.updatePageArrows = function() {
        document.getElementById("itemPageLeft").style.visibility = this.page > 0 ? "visible" : "hidden";
        document.getElementById("itemPageRight").style.visibility = this.page < this.numItems / this.pageSize - 1 ? "visible" : "hidden";
        var str = "Page " + (this.page + 1) + "/" + Math.ceil(this.numItems / this.pageSize);
        document.getElementById("itemPageCount").innerText = str;
    };
    Customizer.prototype.flipPage = function(dir) {
        this.page += dir;
        this.currentRenderFunc();
        this.updatePageArrows();
    };
    Customizer.prototype.iteratePage = function(callbackPerItem) {
        var start = this.page * this.pageSize;
        var end = Math.min(start + this.pageSize, this.numItems);
        for (var i = start, b = 0; i < end; i++, b++) {
            callbackPerItem(i, b);
        }
    };
