    Customizer.prototype.doesItemRequirePhysicalUnlock = function(item) {
        var requiresPhysicalUnlock = item.item_data.unlock !== undefined && item.item_data.unlock !== null && item.item_data.unlock === "physical";
        return requiresPhysicalUnlock;
    };
