    function loggedIn(user) {
        if (playerAccount.isLoggedIn || loggingIn) return;
        loggingIn = true;
        user.getIdToken(true).then(function(idToken) {
            statsEl = document.getElementById("statsMessage");
            statsEl.innerHTML = "Retrieving your stats...";
            statsEl.style.display = "block";
            console.log("Using services server: " + servicesServer);
            try {
                var authWs = new WebSocket(servicesServer);
            } catch (e) {
                console.log(e);
            }
            authWs.onopen = function(e) {
                authWs.send(JSON.stringify({
                    cmd: "auth",
                    uid: user.uid,
                    token: idToken
                }));
                console.log("authWs opened, and auth request sent");
            };
            authWs.onmessage = function(e) {
                var accountDataResponse = JSON.parse(e.data);
                if (accountDataResponse.error) {
                    statsEl.innerHTML = "Database error. Please send us a bug report!";
                    console.log("accountDataResponse Error: " + JSON.stringify(accountDataResponse.error));
                } else {
                    playerAccount.loggedIn(accountDataResponse);
                    updatePlayerStatsDisplay();
                    updateCurrentBalance();
                    customizeWhenReady();
                    sendOneSignalTagsForUser();
                    console.log("logged in");
                    statsEl.style.display = "none";
                    document.getElementById("playerStats").style.display = "flex";
                }
                authWs.close();
            };
            authWs.onclose = function(e) {
                console.log("authWs closed: " + e.code + " " + e.reason);
                loggingIn = false;
            };
            authWs.onerror = function(e) {
                statsEl.innerHTML = '<p style="text-align: left">WebSocket connection failure. Please check your connection at:<br><a href="http://websocketstest.com" target="_window">websocketstest.com</a><br>as well as your firewall and antivirus settings.</p>';
                console.log("authWS Error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
                loggingIn = false;
            };
        }).catch(function(error) {
            console.log(error);
            loggingIn = false;
        });
        document.getElementById("login").style.display = "none";
        document.getElementById("logout").style.display = "block";
        if (user.photoURL) {
            var url = user.photoURL;
            var pd = user.providerData[0];
            if (pd.providerId == "facebook.com") {
                url = "https://graph.facebook.com/" + pd.uid + "/picture";
            }
            document.getElementById("profilePic").src = url;
            document.getElementById("profilePic").style.display = "block";
        }
    }
