    function requestService(command, data, success, fail) {
        try {
            var serviceWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
            if (fail) fail(e);
        }
        serviceWs.onopen = function(e) {
            data.cmd = command;
            serviceWs.send(JSON.stringify(data));
            console.log("services opened, and " + command + " request sent");
        };
        serviceWs.onmessage = function(e) {
            var response = JSON.parse(e.data);
            if (response.error) {
                console.log(command + " error: " + JSON.stringify(response.error));
                if (fail) fail(response.error);
            } else {
                console.log(command + " success");
                if (success) success(response);
            }
            serviceWs.close();
        };
        serviceWs.onclose = function(e) {
            console.log(command + " service closed: " + e.code + " " + e.reason);
            if (success) success(e);
        };
        serviceWs.onerror = function(e) {
            console.log(command + " error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
            if (fail) fail(e);
        };
    }
