    function getFloatingNameWidth(name, size) {
        var context = nameTestCanvas.getContext("2d");
        context.font = "bold " + size + "px Nunito, sans-serif";
        return context.measureText(name).width;
    }
    function fixStringWidth(str, len) {
        len = len || 80;
        var context = nameTestCanvas.getContext("2d");
        context.font = "1em Nunito, sans-serif";
        while (1) {
            var metrics = context.measureText(str);
            if (metrics.width < len) break;
            str = str.substr(0, str.length - 1);
        }
        return str;
    }
    function notify(msg, timeout) {
        var e = document.getElementById("notification");
        e.style.opacity = 0;
        e.style.top = "-3.5em";
        e.style.display = "flex";
        document.getElementById("notificationMessage").innerHTML = msg;
        var anim = 0;
        var animIn = setInterval(function() {
            anim++;
            e.style.opacity = anim / 8;
            e.style.top = anim / 2 - 3.5 + "em";
            if (anim == 8) {
                clearInterval(animIn);
                if (timeout) {
                    setTimeout(function() {
                        dismissNotification();
                    }, timeout);
                }
            }
        }, 32);
    }
    function dismissNotification(callback) {
        var anim = 8;
        var e = document.getElementById("notification");
        var animIn = setInterval(function() {
            e.style.opacity = anim / 8;
            e.style.top = anim / 2 - 3.5 + "em";
            anim--;
            if (anim == 0) {
                clearInterval(animIn);
                e.style.display = "none";
                if (callback) callback();
            }
        }, 32);
    }
