    function randomName() {
        var name, num;
        var n1 = [ "Captain", "Lord", "Supreme", "Master", "Pro", "Noob" ];
        var n2 = [ "Egg", "Yolk", "Shell", "Cluck", "Chick", "Bird" ];
        do {
            num = Math.randomInt(1, 99);
        } while (num == 69);
        if (Math.randomInt(0, 2) == 0) {
            name = n1[Math.randomInt(0, n1.length)] + n2[Math.randomInt(0, n2.length)] + num;
        } else {
            name = n2[Math.randomInt(0, n2.length)] + n1[Math.randomInt(0, n1.length)] + num;
        }
        return name;
    }
    function buyItem(itemId) {
        console.log("buyItem called for item ID: " + itemId);
        try {
            var servicesWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
        }
        servicesWs.onopen = function(e) {
            servicesWs.send(JSON.stringify({
                cmd: "buy",
                uid: playerAccount.firebaseId,
                item_id: itemId
            }));
        };
        servicesWs.onmessage = function(e) {
            purchaseResult = JSON.parse(e.data);
            console.log("purchase response: " + purchaseResult.result);
            switch (purchaseResult.result) {
              case "SUCCESS":
                if (purchaseResult.item_id !== undefined && purchaseResult !== null) {
                    var boughtItem = catalog.findItemById(purchaseResult.item_id);
                    playerAccount.inventory.push(boughtItem);
                }
                playerAccount.currentBalance = purchaseResult.current_balance;
                updateCurrentBalance();
                customizer.boughtItem();
                break;

              case "INSUFFICIENT_FUNDS":
                openAlertDialog("Need More Eggs!", "You need more eggs", {
                    label: "OK",
                    width: "4em",
                    onclick: closeAlertDialog
                }, null, null);
                break;

              case "ALREADY_OWNED":
                openAlertDialog("Already Owned", "You already have this. Try reloading the game.", {
                    label: "OK",
                    width: "4em",
                    onclick: closeAlertDialog
                }, null, null);
                break;

              case "PLAYER_NOT_FOUND":
                openAlertDialog("Uh Oh", "There was a problem. Try logging in again.", {
                    label: "OK",
                    width: "4em",
                    onclick: closeAlertDialog
                }, null, null);
                break;

              case "ITEM_NOT_FOUND":
                openAlertDialog("Uh Oh", "There was a problem. Try reloading the game.", {
                    label: "OK",
                    width: "4em",
                    onclick: closeAlertDialog
                }, null, null);
                break;

              case "ERROR":
              default:
                console.log("buyItem error: " + purchaseResult.error);
                openAlertDialog("Uh Oh", "There was a problem. Try reloading the game.", {
                    label: "OK",
                    width: "4em",
                    onclick: closeAlertDialog
                }, null, null);
                break;
            }
            servicesWs.close();
        };
        servicesWs.onclose = function(e) {
            console.log("servicesWs closed: " + e.code + " " + e.reason);
        };
        servicesWs.onerror = function(e) {
            statsEl.innerHTML = '<p style="text-align: left">WebSocket connection failure. Please check your connection at:<br><a href="http://websocketstest.com" target="_window">websocketstest.com</a><br>as well as your firewall and antivirus settings.</p>';
            console.log("servicesWs Error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
        };
    }
