    function getXsollaToken() {
        console.log("getXsollaToken called");
        if (purchasingEnabled) {
            console.log("getXsollaToken: purchasing already enabled, skipping");
            return;
        }
        try {
            var servicesWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
        }
        servicesWs.onopen = function(e) {
            servicesWs.send(JSON.stringify({
                cmd: "xsollaToken",
                uid: playerAccount.firebaseId
            }));
            console.log("servicesWs opened, and xsollaToken request sent");
        };
        servicesWs.onmessage = function(e) {
            getTokenData = JSON.parse(e.data);
            if (getTokenData.error) {
                console.log("getTokenData Error: " + JSON.stringify(getTokenData.error));
                disableProductPurchasing();
            } else {
                if (getTokenData.result == "SUCCESS") {
                    console.log("got Xsolla token: " + getTokenData.token);
                    enableProductPurchasing(getTokenData.token);
                } else {
                    console.log("failed to get Xsolla token");
                    disableProductPurchasing();
                }
            }
            servicesWs.close();
        };
        servicesWs.onclose = function(e) {
            console.log("servicesWs closed: " + e.code + " " + e.reason);
        };
        servicesWs.onerror = function(e) {
            disableProductPurchasing();
        };
    }
    function enableProductPurchasing(xsollaToken) {
        var options = {
            access_token: xsollaToken,
            sandbox: false,
            lightbox: {
                spinner: "round",
                overlayOpacity: .8
            }
        };
        var s = document.createElement("script");
        s.type = "text/javascript";
        s.async = true;
        s.src = "//static.xsolla.com/embed/paystation/1.0.7/widget.min.js";
        s.addEventListener("load", function(e) {
            XPayStationWidget.on("init", function(e) {
                console.log("store initialized");
                XPayStationWidget.open();
            });
            XPayStationWidget.on("close", function(e) {
                console.log("store closed");
                setTimeout(function() {
                    checkBalance();
                }, 3e3);
            });
            XPayStationWidget.init(options);
        }, false);
        var head = document.getElementsByTagName("head")[0];
        head.appendChild(s);
        globalXsollaToken = xsollaToken;
        purchasingEnabled = true;
    }
