    function customizeWhenReady() {
        customizeWhenReadyIteration(0);
    }
    function customizeWhenReadyIteration(iteration) {
        if (iteration >= 200) {
            return;
        }
        iteration++;
        var ready = customizer !== undefined && customizer !== null && customizer.isReady === true;
        if (!ready) {
            setTimeout(customizeWhenReadyIteration, 100, iteration);
        } else {
            customizer.setupItems();
            customizer.dressUpEgg();
            waitForAuthResult();
        }
    }
    function waitForAuthResult() {
        waitForAuthResultIteration(0);
    }
    function waitForAuthResultIteration(iteration) {
        if (iteration >= 200) {
            return;
        }
        iteration++;
        if (!authAttemptComplete) {
            setTimeout(waitForLoginResultIteration, 100, iteration);
        } else {
            if (!tryShowLinkItem()) {
                tryGiveReward();
                tryShowTaggedItems();
            }
        }
    }
    function tryShowLinkItem() {
        var searchParams = new URLSearchParams(document.location.search);
        if (searchParams.has("showItem") === false) {
            return false;
        }
        var showItemId = parseInt(searchParams.get("showItem"));
        var tryShow = Number.isInteger(showItemId) && catalog.findItemById(showItemId) !== null && linkItemShown === false;
        if (tryShow === false) {
            return false;
        }
        linkItemShown = openItemInCustomizer(showItemId);
        return linkItemShown;
    }
