    function tryGiveReward() {
        if (checkedForReward === true) {
            return;
        }
        if (rewardTag === undefined || rewardTag === null) {
            return;
        }
        if (!playerAccount.isLoggedIn) {
            openAlertDialog("Your Reward", "Uh oh, you gotta log in to get your reward!", {
                label: "Login",
                width: "6em",
                onclick: openLoginDialog
            }, {
                label: "Close",
                width: "6em",
                onclick: closeAlertDialog
            });
            return;
        }
        console.log("tryGiveReward called. firebase ID: " + playerAccount.firebaseId + ", rewardTag: " + rewardTag);
        try {
            var servicesWs = new WebSocket(servicesServer);
        } catch (e) {
            console.log(e);
        }
        servicesWs.onopen = function(e) {
            servicesWs.send(JSON.stringify({
                cmd: "reward",
                firebase_id: playerAccount.firebaseId,
                reward_tag: rewardTag
            }));
        };
        servicesWs.onmessage = function(e) {
            checkedForReward = true;
            rewardResult = JSON.parse(e.data);
            if (rewardResult.error) {
                console.log("giveReward Error: " + JSON.stringify(rewardResult.error));
            } else {
                console.log("giveReward response: " + rewardResult.result);
                var giveRewardDialog = document.getElementById("giveRewardDialog");
                var giveRewardResultText = document.getElementById("giveRewardResultText");
                var giveRewardCompleteButton = document.getElementById("giveRewardCompleteButton");
                giveRewardDialog.style.display = "inline-block";
                switch (rewardResult.result) {
                  case "SUCCESS":
                    var msg = "<h1>EGGSELLENT!!!</h1>";
                    if (rewardResult.eggs_given !== undefined && rewardResult.eggs_given !== null && rewardResult.eggs_given > 0) {
                        msg += '<div style="margin-top: 1em; margin-bottom: 1em">' + rewardResult.eggs_given + " egg reward!";
                        checkBalance();
                    }
                    if (rewardResult.item_ids !== undefined && rewardResult.item_ids !== null && rewardResult.item_ids.length > 0) {
                        for (var i = 0; i < rewardResult.item_ids.length; i++) {
                            var rewardedItem = catalog.findItemById(rewardResult.item_ids[i]);
                            if (!playerAccount.isItemOwned(rewardedItem)) {
                                playerAccount.inventory.push(rewardedItem);
                                console.log("rewarded item id: " + rewardedItem.id);
                            }
                        }
                        msg += '<div style="margin-top: 1em; margin-bottom: 1em">Your new gear is ready to use!</div>';
                    }
                    giveRewardResultText.innerHTML = msg;
                    giveRewardCompleteButton.style = "ssbutton green";
                    break;

                  case "REWARD_PREV_GIVEN":
                    giveRewardResultText.innerText = "You have already received this reward!";
                    giveRewardCompleteButton.style = "ssbutton red";
                    break;

                  case "REWARD_EXPIRED":
                    giveRewardResultText.innerText = "This reward is no longer available";
                    giveRewardCompleteButton.style = "ssbutton red";
                    break;

                  case "REWARD_NOT_FOUND":
                    giveRewardResultText.innerText = "Reward not found";
                    giveRewardCompleteButton.style = "ssbutton red";
                    break;

                  case "ERROR":
                    console.log("error: " + rewardResult.error);
                    giveRewardResultText.innerText = "Uh oh, there was problem";
                    giveRewardCompleteButton.style = "ssbutton red";
                    break;

                  default:
                    giveRewardResultText.innerText = "Uh oh, there was problem. Try logging in again.";
                    giveRewardCompleteButton.style = "ssbutton red";
                    break;
                }
            }
            rewardTag = null;
            listenForOneSignalNotifications();
            servicesWs.close();
        };
        servicesWs.onclose = function(e) {
            console.log("servicesWs closed: " + e.code + " " + e.reason);
            rewardTag = null;
        };
        servicesWs.onerror = function(e) {
            statsEl.innerHTML = '<p style="text-align: left">WebSocket connection failure. Please check your connection at:<br><a href="http://websocketstest.com" target="_window">websocketstest.com</a><br>as well as your firewall and antivirus settings.</p>';
            console.log("servicesWs Error: " + JSON.stringify(e, [ "message", "arguments", "type", "name" ]));
            listenForOneSignalNotifications();
            rewardTag = null;
        };
    }
